prop:hiddenkey:
\begin{proposition}[Hidden-key computational hardness]\label{prop:hiddenkey}
Under the PRF assumption of Theorem~\ref{thm:prf}, no probabilistic polynomial-time learner independent of $s$, with a polynomial-time evaluable output and only polynomially many labeled samples from the uniform distribution on $\ell_0$, has average error at most $1/2-\gamma(n)$ for uniform $s$, where $\gamma(n)\ge1/\operatorname{poly}(n)$. More precisely, a learner with $q(n)$ samples and advantage $\gamma(n)$ gives a PRF distinguisher of advantage at least
\[
 \gamma(n)-\frac{q(n)}{2N}.
\]
\end{proposition}

lem:regularstars:
\begin{lemma}[Regular stars for almost every key]\label{lem:regularstars}
Fix $0<\epsilon<1/4$ and define star-regularity with the threshold $C_0=\max\{64\lceil n\rceil,\lceil128/\epsilon\rceil\}$ from \cref{thm:fast}. For independent fair incidence flips, the probability of failure of star-regularity is at most $e^{-3n}$, where $n=\log_2(2N^3)$. Under the PRF assumption and parameters of Theorem~\ref{thm:prf}, failure occurs for only a negligible fraction of keys.
\end{lemma}

thm:caps:
\begin{theorem}[Pointwise cap mixture and table-polynomial implementation]\label{thm:caps}
Fix $d\ge1$. Let $F$ have a strict rank-$d$ representation and no negative $2\times2$, and let $A$ be any monotone flip of its negative entries. Perturb the row vectors once into linear general position without changing $F$. At any nonempty survivor set, use the uniform row prior $\nu$. There is a cap sampler, depending on the surviving rows but not on the unknown marginal, such that
\begin{equation}\label{eq:capcoverage}
 \forall x\in U,\qquad \E[\1_S(x)\nu(T)]\ge\frac{c_d}{8d},
 \quad c_d=\Pr_{u\sim\mathrm{Unif}(S^{d-1})}
 [u_1\ge\sqrt{1-1/(2d)}].
\end{equation}
Here $c_1=1/2$. Thus Theorem~\ref{thm:main} applies with $\rho=8d/c_d$ in the ideal real-arithmetic model.

For each fixed $d$, given the explicit table of $A$ and rational template vectors of bit length at most $b$, there are randomized and deterministic implementations, polynomial in $|X|,|H|,b,1/\epsilon$, for every $0<\epsilon<1/4$, with
\[
 m=O_d(\log|H|+\log(1/\epsilon)),\qquad
 \tau=\Omega_d(\epsilon/\log(1/\epsilon)).
\]
Queries are intersections of stored cap tests, or such tests split by one row label or one point's row labels. The running time is polynomial in the supplied table size.
\end{theorem}

lem:median:
\begin{lemma}[Noisy integer medians]\label{lem:median}
Suppose $\beta>0$, $|\widehat\beta-\beta|\le\zeta$, and $\beta\ge512\zeta$. Let $f$ be integer-valued in $[L,H]$ on the negative support. Binary search using the query $\mu^-\{f\le t\}$ and threshold $\widehat\beta/2$ returns $v\in[L,H]$ with
\[
 \mu^-\{f\le v\}\ge\beta/2-3\zeta/2,
 \qquad
 \mu^-\{f<v\}<\beta/2+3\zeta/2.
\]
If the answer $\widehat m$ to $m=\mu^-\{f=v\}$ is at most $\widehat\beta/8$, then
\begin{equation}\label{eq:balancedmedian}
 \beta/2-3\zeta/2\le\mu^-\{f\le v\}
 <5\beta/8+21\zeta/8.
\end{equation}
Otherwise $m>\beta/9$.
\end{lemma}

thm:construction:
\begin{theorem}[Construction and ordinary dimension]\label{thm:construction}
Every monotone flip $A$ satisfies $\operatorname{VC}(A)\le2$ and $\rect(A)\ge2^{-15}$. The template has $\sr(F)\le6$ and exactly
\begin{equation}\label{eq:I}
 I=2N^4-\left(\frac{N(N+1)}2\right)^2\ge N^4
\end{equation}
independent flip positions. Set $B_0=\log_2(4eK)$ and $s_0=\lfloor I/(4KB_0)\rfloor$. A random $A$ satisfies
\[
 \Pr[\dc(H_A)\le s_0]\le2^{-I/2}.
\]
Every member also satisfies $\dc(H_A)\le2N+1$. In particular most matrices have $\dc(H_A)=\Omega(N/\log M)$. For every $0<\epsilon<1/4$, all members have a learner with $m=O_\epsilon(\log M)$ and $\tau=\Omega_\epsilon(1)$, by \cref{thm:main} with $\rho=2^{15}$. Independently of the sharp rectangle input, the self-contained cap proof in Appendix~\ref{app:oldgeometry} supplies $\rho=2^{18}$ and the same asymptotic learning bound.
\end{theorem}

thm:prob:
\begin{theorem}[Approximate counting and exact probabilistic dimension]\label{thm:prob}
Fix $0\le\eta<1/2$ and write
\[
 h_2(\eta)=-\eta\log_2\eta-(1-\eta)\log_2(1-\eta),\quad
 c_\eta=1-h_2(\eta)>0,
 \quad s_\eta=\left\lfloor\frac{c_\eta I}{4KB_0}\right\rfloor,
\]
with $0\log 0=0$. For the random incidence-flip matrix,
\begin{equation}\label{eq:approx-prob}
 \Pr[\dc^\eta(H_A)<s_\eta]\le2^{-c_\eta I/2}.
\end{equation}

Consequently most $A$ have $\dc_{1/2}(H_A)=\Omega(N/\log^2M)$ and $\dc^\eta(H_A)=\Omega_\eta(N/\log M)$.
\end{theorem}

lem:exact-prob:
\begin{lemma}[From exact probabilistic to strict dimension]\label{lem:exact-prob}
For every finite nonempty class $H$ with $K=|H|$,
\begin{equation}\label{eq:exact-prob}
 \dc(H)\le(\lceil\log_2K\rceil+1)\dc_{1/2}(H)+1.
\end{equation}
\end{lemma}

lem:finite-minimax:
\begin{lemma}[Finite minimax and pointwise coverage]\label{lem:finite-minimax}
Let $\mathcal A$ be a nonempty finite action set and $Z$ a nonempty finite set of instance types. Let $g_a\in\R^Z$ and $r\in\R$. The following statements are equivalent:
\[
 \forall\mu\in\Delta(Z),\ \max_{a\in\mathcal A}\E_\mu g_a\ge r;
 \qquad
 \exists\lambda\in\Delta(\mathcal A),\ \forall z\in Z,\ \E_\lambda g_a(z)\ge r.
\]
The result also applies when an arbitrary instance set induces only finitely many payoff vectors $(g_a(z))_{a\in\mathcal A}$.
\end{lemma}

lem:product-weights:
\begin{lemma}[From uniform rectangles to product weights]\label{lem:product-weights}
Suppose a property of finite matrices is preserved by repeating rows and columns. Suppose every matrix with that property has a monochromatic rectangle with row fraction at least $a$ and column fraction at least $b$. Then every such matrix has rectangle ratio at least $ab$ under arbitrary product distributions.
\end{lemma}

lem:ties:
\begin{lemma}[Tie conventions and strict realization]\label{lem:ties}
For any finite family of predictions obtained from a $d$-dimensional embedding with the convention $\sign(0)=+1$ or $-1$, the same Boolean prediction matrix has a strict realization in dimension at most $d+1$. The probabilistic lower bounds in \cref{thm:prob,lem:exact-prob} remain valid under either tie rule or when all zero scores count as errors.
\end{lemma}

lem:params:
\begin{lemma}[Exact parameters]\label{lem:params}
For a finite nonempty $H$, $\rho\ge1$, $\rect(H)\ge1/\rho$, and $0<\epsilon<1/4$, \cref{thm:main} holds with
\begin{align}
 r&=1/\rho,&P&=1+\lceil4\rho\ln(8/\epsilon)\rceil,&\tau&=\epsilon/(24P),\label{eq:params1}\\
 B&=\ln K+\ln(8/\epsilon)+1,&R&=\lceil8\rho(B+\ln(2/\epsilon))\rceil,&m&=3R+1.\label{eq:params2}
\end{align}
\end{lemma}

lem:mixture:
\begin{lemma}[A marginal-free rectangle mixture]\label{lem:mixture}
Assume $H$ is finite, $0<r\le\rect(H)$, and fix nonempty $U\subseteq X$, nonempty $V\subseteq H$, and a distribution $\nu$ on $V$. There is a distribution $\lambda$ over monochromatic rectangles $S_R\times T_R\subseteq U\times V$ such that
\begin{equation}\label{eq:coverage}
 \forall x\in U,\qquad
 \E_{R\sim\lambda}\bigl[\1_{S_R}(x)\nu(T_R)\bigr]\ge r.
\end{equation}
This distribution can be computed from $(H,U,V,\nu)$ without a query about $D$.
\end{lemma}

thm:energy:
\begin{lemma}[Finite energy and threshold counting]\label{thm:energy}
Let $P_0$ be a probability distribution on a finite set $Z$, and let $r_1,\ldots,r_K\in L^2(P_0)$. Set
\[
 \Gamma_{ij}=\E_{P_0}r_i r_j,\qquad \Lambda=\|\Gamma\|_\op.
\]
For every $a:Z\to\R$,
\begin{equation}\label{eq:energy}
 \sum_{j=1}^K\bigl(\E_{P_0}r_j a\bigr)^2
 \leq\Lambda\E_{P_0}a^2.
\end{equation}
In particular, if $|a|\leq1$ and $\tau>0$, then
\begin{equation}\label{eq:count}
 \bigl|\{j:|\E_{P_0}r_j a|>\tau\}\bigr|\tau^2\leq\Lambda.
\end{equation}
More generally, for any finite list of real numbers $c_i$, $\tau\geq0$, and $\sum_i c_i^2\leq\Lambda$, one has $|\{i:\tau<|c_i|\}|\tau^2\leq\Lambda$.
\end{lemma}

thm:barrier:
\begin{theorem}[Joint-distribution SQ barrier]\label{thm:barrier}
Let $\mu$ be a full-support distribution on $X$ and let $P_0=\mu\otimes\mathrm{Unif}\{-1,+1\}$. For $j\in[K]$, let $P_j$ be the labeled distribution arising from some $D_j$ and $h_j\in\cH$. Put
\[
 r_j=\frac{P_j}{P_0}-1,\qquad
 \Gamma_{ij}=\E_{P_0}r_i r_j,\qquad
 \Lambda=\|\Gamma\|_\op,\qquad R=K/\Lambda.
\]
Any randomized adaptive $(m,\tau)$-SQ learner satisfying \eqref{eq:guarantee} obeys
\begin{equation}\label{eq:joint}
 1-2\epsilon\leq\sqrt{\frac\Lambda K}+
 \frac{m\Lambda}{K\tau^2},
 \quad\text{equivalently}\quad
 \frac m{\tau^2}\geq(1-2\epsilon)R-\sqrt R.
\end{equation}
Consequently, for $\epsilon<1/4$,
\begin{equation}\label{eq:Rbound}
 R\leq4+4m/\tau^2.
\end{equation}
\end{theorem}

thm:forster:
\begin{theorem}[Spectral sign-rank bounds]\label{thm:forster}
If $A\in\R^{N\times K}$ satisfies $|A_{xj}|\geq1$ for all entries, then
\begin{equation}\label{eq:forster}
 \sr(\sign A)\geq\frac{\sqrt{NK}}{\|A\|_\op}.
\end{equation}
If $M\in\{-1,+1\}^{N\times K}$ and $G=M^\top\diag(\mu)M$ for any distribution $\mu$ on its rows, then
\begin{equation}\label{eq:weighted}
 \sr(M)\geq\sqrt{K/\|G\|_\op}.
\end{equation}
\end{theorem}

thm:plane:
\begin{theorem}[Projective-plane incidence classes]\label{thm:plane}
For each prime $q\geq2$, let $X_q$ be the points of the projective plane over $\mathbb F_q$, and let $\cH_q$ have one hypothesis per line, positive on that line and negative elsewhere. Set $N=q^2+q+1$ and $k=q+1$. Then:
\begin{align}
 \frac{q+1}{\sqrt q}&\leq\dc(\cH_q)\leq2q+3,\label{eq:planedc}\\
 \frac{|J|}{\|[\E_\mu h_i h_j]_{i,j\in J}\|_\op}&\leq16
 \quad\text{for every distribution $\mu$ and nonempty $J\subseteq\cH_q$}.
 \label{eq:planeplain}
\end{align}
There is a distribution-independent $N$-query tolerance-$\tau$ learner of loss at most $\tau$. For each \emph{fixed} $D$ and $0<\epsilon<1/4$, there is a learner allowed to depend on $D$, with tolerance $\epsilon/2$ and
\[
 m_D\leq1+s+\binom{s}{2},\qquad
 s=\left\lceil\frac{4\log N+2}{\epsilon}\right\rceil,
\]
that has loss at most $\epsilon$ for every target. Here $\log$ is natural.
Nevertheless every \emph{single} learner satisfying \eqref{eq:guarantee}, with $m\geq1$, $0<\tau\leq1$, and $\epsilon<1/4$, satisfies
\begin{equation}\label{eq:plane19}
 \dc(\cH_q)\leq19m/\tau^2.
\end{equation}
\end{theorem}

thm:tree:
\begin{theorem}[Marginal-branching and approximate probabilistic bounds]\label{thm:tree}
Let $B=\lceil2/\tau\rceil+1$, with $0<\tau\leq1$. For a deterministic learner satisfying \eqref{eq:guarantee}, decompose each query as
\[
 q(x,y)=a(x)+yb(x),\quad
 a(x)=\tfrac12(q(x,+1)+q(x,-1)),\quad
 b(x)=\tfrac12(q(x,+1)-q(x,-1)).
\]
Construct its marginal-response tree as follows. If $a$ is constant, retain only the answer equal to that constant. Otherwise retain the $B$ equally spaced answers in $[-1,1]$. Let $u$ be the maximum number of nonconstant-$a$ nodes on a retained root-to-leaf path. Then
\begin{equation}\label{eq:tree}
 \dc(\cH)\leq(m+1)B^u.
\end{equation}
In particular, a deterministic correlational-only learner has $\dc(\cH)\leq m+1$.
For an arbitrary randomized learner satisfying \eqref{eq:guarantee},
\begin{equation}\label{eq:approx}
 \dc^{\epsilon}(\cH)\leq B^m.
\end{equation}
\end{theorem}

prop:cap-bound:
\begin{proposition}[Independent constant rectangle bound]\label{prop:cap-bound}
Let $c_d$ be the normalized surface measure of the cap of Section~\ref{sec:caps} on $S^{d-1}$, $d\ge2$. Every matrix $F$ of sign-rank at most $d$ satisfies $\rect(F)\ge c_d/(4d)$. If $F$ has no negative $2\times2$, every monotone flip $A$ satisfies $\rect(A)\ge c_d/(8d)$. In particular, for $d=6$ this is greater than $2^{-18}$.
\end{proposition}
